import json, re, collections
p = 'proyectos/farmasi-799'
fuentes = {x['source_name']: x for x in json.load(open(f'{p}/registros/fuentes_799.json'))}
cobrizo_list = json.load(open(f'{p}/historial/modelo_D_todas/SELECCION_COBRIZO_CONFIRMADA.json'))
cobrizo_names = {x['source_name'] for x in cobrizo_list}
html = open(f'{p}/DASHBOARD_FARMASI_799.html').read()
m = re.search(r'const data = (\{.*?\});', html)
dash_data = json.loads(m.group(1))
dash_map = {x['name']: x['cluster'] for x in dash_data['items']}

for x in dash_data['items']:
    name = x['name']
    num = int(name[3:8])
    if name in cobrizo_names:
        if num <= 8554:
            dash_map[name] = 'Grupales con Modelo Cobrizo / Equipo'
        else:
            dash_map[name] = 'Modelo Vestido Cobrizo'
    elif dash_map[name] in ('Modelo Vestido Cobrizo', 'Grupales con Modelo Cobrizo / Equipo'):
        dash_map[name] = 'Tomas Complementarias / Cobertura'

counts = collections.defaultdict(lambda: collections.Counter())
for name, f in fuentes.items():
    c = dash_map[name]
    counts[c]['total'] += 1
    counts[c][f['estado']] += 1
    if f.get('reemplazo_en_revision'):
        counts[c]['reemplazo_d'] += 1
    if f.get('correccion_en_revision'):
        counts[c]['correccion_d'] += 1

for c, cnt in counts.items():
    print(f'{c:40s}: {dict(cnt)}')
""

